export type NoveltyLabel = "Low" | "Moderate" | "High" | "Very High";
export type FeasibilityLabel = "Difficult" | "Moderate" | "Feasible" | "Very Feasible";

export function getNoveltyLabel(score: number): NoveltyLabel {
  if (score >= 0.8) return "Very High";
  if (score >= 0.6) return "High";
  if (score >= 0.3) return "Moderate";
  return "Low";
}

export function getFeasibilityLabel(score: number): FeasibilityLabel {
  if (score >= 8) return "Very Feasible";
  if (score >= 6) return "Feasible";
  if (score >= 3) return "Moderate";
  return "Difficult";
}

export function getScoreColor(score: number, scale: "novelty" | "feasibility"): string {
  const normalized = scale === "feasibility" ? score / 10 : score;
  if (normalized >= 0.8) return "text-green-600";
  if (normalized >= 0.6) return "text-emerald-500";
  if (normalized >= 0.3) return "text-amber-500";
  return "text-red-500";
}

export function getScoreBg(score: number, scale: "novelty" | "feasibility"): string {
  const normalized = scale === "feasibility" ? score / 10 : score;
  if (normalized >= 0.8) return "bg-green-100 text-green-800";
  if (normalized >= 0.6) return "bg-emerald-100 text-emerald-800";
  if (normalized >= 0.3) return "bg-amber-100 text-amber-800";
  return "bg-red-100 text-red-800";
}

import { describe, it, expect } from "vitest";
import {
  getNoveltyLabel,
  getFeasibilityLabel,
  getScoreColor,
  getScoreBg,
} from "@/lib/score-utils";

describe("getNoveltyLabel", () => {
  it("returns Low for scores below 0.3", () => {
    expect(getNoveltyLabel(0)).toBe("Low");
    expect(getNoveltyLabel(0.29)).toBe("Low");
  });

  it("returns Moderate for scores 0.3–0.59", () => {
    expect(getNoveltyLabel(0.3)).toBe("Moderate");
    expect(getNoveltyLabel(0.5)).toBe("Moderate");
    expect(getNoveltyLabel(0.59)).toBe("Moderate");
  });

  it("returns High for scores 0.6–0.79", () => {
    expect(getNoveltyLabel(0.6)).toBe("High");
    expect(getNoveltyLabel(0.7)).toBe("High");
    expect(getNoveltyLabel(0.79)).toBe("High");
  });

  it("returns Very High for scores >= 0.8", () => {
    expect(getNoveltyLabel(0.8)).toBe("Very High");
    expect(getNoveltyLabel(1.0)).toBe("Very High");
  });
});

describe("getFeasibilityLabel", () => {
  it("returns Difficult for scores below 3", () => {
    expect(getFeasibilityLabel(0)).toBe("Difficult");
    expect(getFeasibilityLabel(2)).toBe("Difficult");
  });

  it("returns Moderate for scores 3–5", () => {
    expect(getFeasibilityLabel(3)).toBe("Moderate");
    expect(getFeasibilityLabel(5)).toBe("Moderate");
  });

  it("returns Feasible for scores 6–7", () => {
    expect(getFeasibilityLabel(6)).toBe("Feasible");
    expect(getFeasibilityLabel(7)).toBe("Feasible");
  });

  it("returns Very Feasible for scores >= 8", () => {
    expect(getFeasibilityLabel(8)).toBe("Very Feasible");
    expect(getFeasibilityLabel(10)).toBe("Very Feasible");
  });
});

describe("getScoreColor", () => {
  it("returns correct color classes for novelty scale", () => {
    expect(getScoreColor(0.1, "novelty")).toBe("text-red-500");
    expect(getScoreColor(0.4, "novelty")).toBe("text-amber-500");
    expect(getScoreColor(0.7, "novelty")).toBe("text-emerald-500");
    expect(getScoreColor(0.9, "novelty")).toBe("text-green-600");
  });

  it("normalizes feasibility scale (0-10) to 0-1", () => {
    expect(getScoreColor(2, "feasibility")).toBe("text-red-500");
    expect(getScoreColor(5, "feasibility")).toBe("text-amber-500");
    expect(getScoreColor(7, "feasibility")).toBe("text-emerald-500");
    expect(getScoreColor(9, "feasibility")).toBe("text-green-600");
  });
});

describe("getScoreBg", () => {
  it("returns correct bg classes for novelty scale", () => {
    expect(getScoreBg(0.1, "novelty")).toBe("bg-red-100 text-red-800");
    expect(getScoreBg(0.9, "novelty")).toBe("bg-green-100 text-green-800");
  });

  it("normalizes feasibility scale (0-10) to 0-1", () => {
    expect(getScoreBg(2, "feasibility")).toBe("bg-red-100 text-red-800");
    expect(getScoreBg(9, "feasibility")).toBe("bg-green-100 text-green-800");
  });
});

